parameters.jsonBody:
={
  "fields": {
    "Service": "{{ $fromAI('service', 'The service booked, e.g. cut or color') }}",
    "Start Time": "{{ $fromAI('start_time', 'The confirmed ISO 8601 start time of the appointment') }}",
    "Status": "Confirmed",
    "Calendly Event URI": "{{ $fromAI('event_id', 'The id field (not the htmlLink) returned by the calendar booking tool for this appointment') }}",
    "Created Via": "{{ $fromAI('channel', 'The channel the booking came from: Website, SMS, or WhatsApp') }}",
    "Session ID": "{{ $fromAI('session_id', 'The conversation session id given to you in this conversation -- for website chat this is the Session ID line at the start of the conversation, for WhatsApp/SMS this is the client phone number. Always pass this exact value.') }}",
    "Execution ID": "{{ $execution.id }}",
    "Client": {{ (() => { const c = $fromAI('client_id', 'The Airtable record id (starts with rec) of the client this appointment belongs to -- the id field returned by Find Client Record or Save Client Record earlier in this same conversation. Always provide this.'); return c ? JSON.stringify([c]) : '[]'; })() }}
  }
}
